package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for {@link MathUtils#binomialCoefficient(int, int)}.
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_binomialCoefficient_TriageGen1Test {

    @Test
    public void testBinomialCoefficient_BaseCases() {
        // Case: n == k (returns 1)
        assertEquals(1L, MathUtils.binomialCoefficient(5, 5));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // Case: k == 0 (returns 1)
        assertEquals(1L, MathUtils.binomialCoefficient(5, 0));
        assertEquals(1L, MathUtils.binomialCoefficient(0, 0));

        // Case: k == 1 (returns n)
        assertEquals(5L, MathUtils.binomialCoefficient(5, 1));
        assertEquals(10L, MathUtils.binomialCoefficient(10, 1));

        // Case: k == n - 1 (returns n)
        assertEquals(5L, MathUtils.binomialCoefficient(5, 4));
        assertEquals(10L, MathUtils.binomialCoefficient(10, 9));
    }

    @Test
    public void testBinomialCoefficient_StandardValues() {
        // (5 choose 2) = 10
        assertEquals(10L, MathUtils.binomialCoefficient(5, 2));
        // (6 choose 3) = 20
        assertEquals(20L, MathUtils.binomialCoefficient(6, 3));
        // (10 choose 3) = 120
        assertEquals(120L, MathUtils.binomialCoefficient(10, 3));
    }

    @Test
    public void testBinomialCoefficient_LargeValues() {
        // Test values that are large but within long range
        // (60 choose 30) is a large number
        long result = MathUtils.binomialCoefficient(60, 30);
        // Expected value calculation: 118264581564861424
        assertEquals(118264581564861424L, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NLessThanK() {
        // must have n >= k
        MathUtils.binomialCoefficient(5, 6);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testBinomialCoefficient_NNegative() {
        // must have n >= 0
        MathUtils.binomialCoefficient(-1, 0);
    }

    @Test
    public void testBinomialCoefficient_OverflowHandling() {
        // The method uses binomialCoefficientDouble and checks if result == Long.MAX_VALUE
        // Since we cannot easily trigger the exact Long.MAX_VALUE via Math.round(double) 
        // without knowing the internal precision, we test the logic via very large inputs.
        // Note: In a real scenario, n=1000, k=500 would definitely overflow a long.
        try {
            MathUtils.binomialCoefficient(1000, 500);
        } catch (ArithmeticException e) {
            assertEquals("result too large to represent in a long integer", e.getMessage());
        } catch (Exception e) {
            // Depending on how binomialCoefficientDouble behaves, it might return Infinity
            // and Math.round(Infinity) returns Long.MAX_VALUE.
        }
    }

    @Test
    public void testBinomialCoefficient_Symmetry() {
        // (n choose k) should equal (n choose n-k)
        // Even though the code uses symmetry for large k, the method should return correct results.
        long val1 = MathUtils.binomialCoefficient(20, 5);
        long val2 = MathUtils.binomialCoefficient(20, 15);
        assertEquals(val1, val2);
        assertEquals(15504L, val1);
    }
}
